const foes=[{name:'Gloom Slime',emoji:'🟣',hp:25,attack:5,xp:14,shards:2,kind:'slime',desc:'A shy creature of the undergrowth.'},{name:'Duskling',emoji:'🦇',hp:32,attack:7,xp:19,shards:3,kind:'bat',desc:'A little night spirit with a big attitude.'},{name:'Mossfang',emoji:'🐺',hp:43,attack:8,xp:24,shards:4,kind:'wolf',desc:'A forest guardian, all teeth and tangled vines.'},{name:'Ashen Wisp',emoji:'👻',hp:51,attack:9,xp:31,shards:5,kind:'wisp',desc:'A lost soul drifting between worlds.'},{name:'Thornback',emoji:'🦔',hp:65,attack:11,xp:38,shards:6,kind:'thorn',desc:'A bramble beast with a surprisingly soft center.'},{name:'Crownless Knight',emoji:'🛡️',hp:92,attack:13,xp:55,shards:10,kind:'boss',desc:'The gatekeeper to a throne left vacant.'}];
const defaults={hp:34,mp:18,maxHp:34,maxMp:18,level:1,xp:0,shards:0,tonics:2,party:[],wins:0,tames:0,foeIndex:0,progress:0,chapter:0,flags:{},};
let S;try{S={...defaults,...JSON.parse(localStorage.getItem('crimson-crown-save')||'{}')};S.flags={...defaults.flags,...(S.flags||{})};S.party=S.party||[]}catch{S={...defaults}}let foe=null,foeHp=0,busy=false,storyStep=0;
const save=()=>{localStorage.setItem('crimson-crown-save',JSON.stringify(S));$('#saveTime').textContent='JUST NOW'};
const toast=t=>{let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2100)};
function journal(title,detail,glyph='✦'){let list=$('#journalList');let el=document.createElement('div');el.className='journal-entry';el.innerHTML=`<span class="journal-glyph">${glyph}</span><div><b>${title}</b><small>${detail}</small></div>`;list.prepend(el);while(list.children.length>3)list.lastChild.remove();$('#noteCount').textContent=String(list.children.length).padStart(2,'0')}
function refresh(){let hpPct=Math.max(0,S.hp/S.maxHp*100),mpPct=Math.max(0,S.mp/S.maxMp*100);$('#hpBar').style.width=hpPct+'%';$('#mpBar').style.width=mpPct+'%';$('#hpText').textContent=`${S.hp} / ${S.maxHp}`;$('#mpText').textContent=`${S.mp} / ${S.maxMp}`;$('#level').textContent=String(S.level).padStart(2,'0');$('#shardCount').textContent=S.shards;$('#shardCount2').textContent=S.shards;$('#tonicCount').textContent=S.tonics;let need=30+(S.level-1)*25;$('#xpBar').style.width=Math.min(100,S.xp/need*100)+'%';$('#xpText').textContent=`${S.xp} / ${need}`;let conq=Math.min(100,S.wins*14+S.tames*9);$('#questPercent').textContent=conq+'%';$('#questBar').style.width=conq+'%';$('#questHint').textContent=S.wins?`${S.wins} battle${S.wins===1?'':'s'} won · ${S.tames} pact${S.tames===1?'':'s'} sealed`:'Win your first battle to begin';$('#partyCount').textContent=String(S.party.length+1).padStart(2,'0')+' / 03';$('#partyList').innerHTML=`<div class="party-member"><span class="party-avatar hero">♟</span><div class="party-info"><b>Seren</b><small>VAMPIRE · LV ${S.level}</small></div><span class="party-hp">${S.hp}/${S.maxHp}</span></div>`+S.party.map(p=>`<div class="party-member"><span class="party-avatar">${p.emoji}</span><div class="party-info"><b>${p.name}</b><small>PACTBOUND COMPANION</small></div><span class="party-hp">✦</span></div>`).join('');$('#tameHint').textContent=S.party.length?'♧ '+S.party.length+' companion'+(S.party.length===1?'':'s')+' by your side':'＋ Tame a monster to recruit it';$('#tameHint').onclick=()=>toast(S.party.length?S.party.map(x=>x.name).join(' · '):'Weaken a foe and offer a pact!');if(foe){$('#enemyDisplay').innerHTML=`<span class="enemy-emoji">${foe.emoji}</span><div class="enemy-meta"><b>${foe.name}</b><small>${foe.desc}</small><div class="enemy-meter"><i style="width:${Math.max(0,foeHp/foe.hp*100)}%"></i></div></div><span class="enemy-hp">${Math.max(0,foeHp)} / ${foe.hp} HP</span>`;let chance=Math.max(10,Math.min(90,Math.round((1-foeHp/foe.hp)*75+15)));$('#tameChance').textContent=S.shards>=1?`1 shard · ${chance}% chance`:'Need 1 blood shard';$('#tameChance').dataset.chance=chance;$$('.action-btn').forEach(b=>b.disabled=busy);$('#tameHint').disabled=false}}
function beginEncounter(){if(S.hp<=0){S.hp=S.maxHp;S.mp=S.maxMp;refresh()}let idx=Math.min(S.foeIndex,foes.length-1);foe={...foes[idx]};if(idx===foes.length-1){foe.hp+=Math.floor(S.wins/6)*10;foe.attack+=Math.floor(S.wins/6)*2}foeHp=foe.hp;busy=false;$('#sceneCanvas').classList.add('in-battle');$('#sceneState').textContent='IN BATTLE';$('#sceneHint').textContent='Choose your move carefully...';$('#encounterBtn').classList.add('hidden');$('#encounterRow').classList.add('hidden');$('#battlePanel').classList.remove('hidden');$('#storyCard').classList.add('hidden');$('#battleTitle').textContent=`A wild ${foe.name} appears!`;$('#combatLog').textContent=`${foe.name} blocks your path. What will you do?`;$('#spriteArea').innerHTML=`<div class="hero-sprite"><img src="assets/protagonist.jpg" alt="Seren" /></div><div class="enemy-shadow"></div><div class="enemy-sprite">${foe.emoji}</div>`;refresh()}
function log(text){$('#combatLog').textContent=text}
function enemyTurn(){if(!foe)return;busy=true;refresh();setTimeout(()=>{if(!foe)return;let dmg=Math.max(1,foe.attack+Math.floor(Math.random()*4)-Math.floor(S.level*.65));S.hp=Math.max(0,S.hp-dmg);log(`${foe.name} hits Seren for ${dmg} damage.`);refresh();setTimeout(()=>{if(S.hp<=0){S.hp=Math.max(1,Math.floor(S.maxHp*.55));S.mp=Math.max(0,Math.floor(S.maxMp*.5));endBattle(false)}else{busy=false;refresh();$('#turnBadge')?.classList.remove('enemy-turn')}},500)},420)}
function endBattle(won,tamed=false){let oldFoe=foe;foe=null;busy=false;$('#battlePanel').classList.add('hidden');$('#sceneCanvas').classList.remove('in-battle');$('#sceneState').textContent='EXPLORATION';$('#sceneHint').textContent=won?'The forest grows quiet again.':'You retreat to catch your breath.';$('#encounterBtn').classList.remove('hidden');$('#encounterRow').classList.remove('hidden');$('#encounterBtn').innerHTML='EXPLORE <span>→</span>';if(won){if(tamed){$('#encounterHeading').textContent=`${oldFoe.name.toUpperCase()} JOINS YOUR COVEN`;$('#encounterDescription').textContent='Your new companion chirps happily at your side.';$('#storyText').textContent=`${oldFoe.name} accepts your pact. The system flashes: “Companion acquired. Your coven grows stronger.”`;$('#storyAttribution').textContent='— A SMALL, SURPRISINGLY FRIENDLY CONTRACT'}else{$('#encounterHeading').textContent='VICTORY · THE PATH IS CLEAR';$('#encounterDescription').textContent=`You defeated ${oldFoe.name} and earned ${oldFoe.xp} EXP.`;$('#storyText').textContent=`The creature dissolves into warm motes of light. Your system chimes: “Threat neutralized. The path to the throne is one step closer.”`;$('#storyAttribution').textContent='— SYSTEM MESSAGE, PROBABLY'}$('#sceneCaption').innerHTML=`<span class="caption-icon">✦</span><span>${tamed?'“We can do this together.”':'“Was that... experience points? This is really happening.”'}</span>`}else{$('#encounterHeading').textContent='A NARROW ESCAPE';$('#encounterDescription').textContent='Restored some strength. The creature still waits in the woods.';$('#storyText').textContent='You stumble back, heart racing. Whatever this world is, you will have to be stronger to survive it.';$('#storyAttribution').textContent='— SEREN, VERY MUCH STILL ALIVE'}$('#storyCard').classList.remove('hidden');$('#spriteArea').innerHTML=`<div class="hero-sprite"><img src="assets/protagonist.jpg" alt="Seren" /></div>`;refresh();save()}
function victory(tame=false){let old=foe;if(tame){S.party.push({name:old.name,emoji:old.emoji});S.tames++;S.shards=Math.max(0,S.shards-1);journal('Pact sealed',`${old.name} joins your coven.`,'♧')}else{S.wins++;S.xp+=old.xp;S.shards+=old.shards;journal('Battle won',`${old.name} · +${old.xp} EXP · +${old.shards} shards`,'⚔');let threshold=30+(S.level-1)*25;while(S.xp>=threshold){S.xp-=threshold;S.level++;S.maxHp+=8;S.maxMp+=4;S.hp=S.maxHp;S.mp=S.maxMp;threshold=30+(S.level-1)*25;toast(`Level up! Seren is now level ${S.level}.`)}S.foeIndex=Math.min(foes.length-1,S.foeIndex+1)}S.progress=Math.min(100,S.progress+14);endBattle(true,tame)}
function doAction(type){if(!foe||busy)return;busy=true;let damage=0;if(type==='attack'){damage=8+Math.floor(Math.random()*6)+S.level*2;foeHp-=damage;log(`Seren strikes ${foe.name} for ${damage} damage!`)}else if(type==='skill'){if(S.mp<12){busy=false;log('Not enough MP! Choose another action.');refresh();return}S.mp-=12;damage=13+Math.floor(Math.random()*8)+S.level*2;foeHp-=damage;let heal=Math.min(S.maxHp-S.hp,Math.ceil(damage*.42));S.hp+=heal;log(`Crimson Drain deals ${damage} damage and restores ${heal} HP.`)}else if(type==='item'){if(S.tonics<=0){busy=false;log('You have no tonics left.');refresh();return}if(S.hp>=S.maxHp){busy=false;log('Your HP is already full. Save that tonic for later.');refresh();return}S.tonics--;let heal=Math.min(18,S.maxHp-S.hp);S.hp+=heal;log(`Seren drinks a Bloodroot Tonic and restores ${heal} HP.`)}else if(type==='tame'){if(S.party.length>=2){busy=false;log('Your coven is full. You can have up to two companions.');refresh();return}if(S.shards<1){busy=false;log('You need at least 1 Blood Shard to offer a pact.');refresh();return}S.shards--;let chance=Number($('#tameChance').dataset.chance||20),roll=Math.random()*100;if(roll<chance){log(`${foe.name} accepts the pact!`);refresh();setTimeout(()=>victory(true),650);return}else{log(`${foe.name} rejects the pact and lashes out!`);refresh();setTimeout(()=>enemyTurn(),550);return}}refresh();if(foeHp<=0){setTimeout(()=>victory(),550);return}setTimeout(()=>enemyTurn(),600)}
$('#encounterBtn').addEventListener('click',beginEncounter);$$('.action-btn').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));document.addEventListener('keydown',e=>{if($('#helpModal').classList.contains('hidden')===false)return;if(['1','2','3','4'].includes(e.key)&&!$('#battlePanel').classList.contains('hidden')){e.preventDefault();doAction(['attack','skill','tame','item'][Number(e.key)-1])}if(e.key==='Enter'&&$('#battlePanel').classList.contains('hidden'))$('#encounterBtn').click()});$('#helpBtn').onclick=()=>$('#helpModal').classList.remove('hidden');$('#closeHelp').onclick=$('#gotIt').onclick=()=>$('#helpModal').classList.add('hidden');$('#helpModal').addEventListener('click',e=>{if(e.target.id==='helpModal')e.currentTarget.classList.add('hidden')});$('#storyContinue').onclick=()=>{$('#storyText').textContent='The system has a primary objective: “Become the Demon King.” It might be a lot to ask of someone who still misses her old commute.';$('#storyAttribution').textContent='— OBJECTIVE ACCEPTED (AUTOMATICALLY)';$('#sceneCaption').innerHTML='<span class="caption-icon">✦</span><span>“Become... the Demon King? I suppose I should start with surviving the woods.”</span>';$('#storyContinue').textContent='UNDERSTOOD ✓';$('#storyContinue').disabled=true;$('#storyContinue').style.opacity='.5';S.flags.intro=true;save()};$('#soundBtn').onclick=()=>{let on=$('#soundBtn').dataset.on==='1';$('#soundBtn').dataset.on=on?'0':'1';$('#soundBtn').innerHTML=on?'♫ <span>SOUND OFF</span>':'♫ <span>SOUND ON</span>';toast(on?'Sound off':'A haunting little tune would play here…')};
function init(){if(!S.flags.intro){journal('A new beginning','Reborn in the Duskwood. The system has a quest for you.','✦')}else{$('#storyText').textContent='The system has a primary objective: “Become the Demon King.” It might be a lot to ask of someone who still misses her old commute.';$('#storyAttribution').textContent='— OBJECTIVE ACCEPTED (AUTOMATICALLY)';$('#sceneCaption').innerHTML='<span class="caption-icon">✦</span><span>“Become... the Demon King? I suppose I should start with surviving the woods.”</span>';$('#storyContinue').textContent='UNDERSTOOD ✓';$('#storyContinue').disabled=true;$('#storyContinue').style.opacity='.5'}if(S.wins+journal.length>0&&S.wins>0){}if(S.wins)journal('The journey so far',`${S.wins} victories · ${S.tames} companions recruited`,'♛');refresh();save()}
init();
})();

